            new Car("Red"),
            new Car("Blue"),
            new Car("Red"),
            new Car("Blue"),
            new Car("Red"),
            new Car("Green"),
            new Car("Green"),
            new Car("Green"),
            new Car("Green"),
            new Car("Green")
